select '00000000-0000-4000-9100-003200000000'::uuid, '00000000-0000-4000-8000-000000000016'::uuid, 'trei-poezii-din-autobuzul-104-demo-32',
  $demo$Trei poezii din autobuzul 104$demo$, $demo$Trei poezii scrise pe telefon, în picioare, pe traseul 104, între cartier și liceu: una despre ora întâi, una despre o tablă plină de ecuații pe care nimeni nu le mai șterge și una despre ultima stație, unde coboară toți, dar nu toți în același oraș.$demo$, 'ro',
  (select id from public.categories where slug = 'poetry'),
